B.LO=new A.aF("C\xe1lculo tipado","Los tipos num\xe9ricos pueden combinarse en expresiones.","void main() {\n  int cantidad = 3;\n  double precio = 9.5;\n  double total = cantidad * precio;\n  print(total);\n}","28.5")
B.Mo=new A.aF("Inspeccionar tipos","runtimeType ayuda a observar el tipo real de un valor.","void main() {\n  var nombre = 'Ana';\n  var edad = 21;\n  print(nombre.runtimeType);\n  print(edad.runtimeType);\n}","String\nint")
